 // 30 days\n        if expiry > max_expiry {\n            return Err(Error::ExpiryTooFar);\n        }\n\n        Ok(())\n    }\n\n    fn store_order(\n        env: &Env,\n        user: &Address,\n        amount: i128,\n        price: i128,\n        expiry: u64,\n    ) -> u64 {\n        let order_id = Self::get_next_order_id(env);\n\n        env.storage().persistent().set(\n            &order_id,\n            &Order {\n                user: user.clone(),\n                amount,\n                price,\n                expiry,\n            },\n        );\n\n        order_id\n    }\n\n    fn get_next_order_id(env: &Env) -> u64 {\n        let current: u64 = env.storage()\n            .instance()\n            .get(&Symbol::new(env, "order_id"))\n            .unwrap_or(0);\n        let next = current + 1;\n        env.storage().instance().set(&Symbol::new(env, "order_id"), &next);\n        next\n    }\n}\n\n#[contracttype]\n#[derive(Clone, Debug, Eq, PartialEq)]\npub struct Order {\n    pub user: Address,\n    pub amount: i128,\n    pub price: i128,\n    pub expiry: u64,\n}\n\n#[contracttype]\n#[derive(Clone, Debug, Eq, PartialEq)]\npub enum Error {\n    InvalidAmount = 1,\n    AmountTooLarge = 2,\n    InvalidPrice = 3,\n    ExpiryInPast = 4,\n    ExpiryTooFar = 5,\n}\n'})})}),(0,a.jsx)(i.A,{value:"test",label:"Test",children:(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{className:"language-rust",metastring:"illustrative",children:"#[test]\nfn test_validation_invalid_amount() {\n    let env = Env::default();\n    let contract_id = env.register_contract(None, ValidatedContract);\n    let client = ValidatedContractClient::new(&env, &contract_id);\n\n    let user = Address::generate(&env);\n    let expiry = env.ledger().timestamp() + 3600;\n\n    env.mock_all_auths();\n\n    // Test negative amount\n    let result = client.try_create_order(&user, &-100, &1000, &expiry);\n    assert_eq!(result, Err(Ok(Error::InvalidAmount)));\n\n    // Test zero amount\n    let result = client.try_create_order(&user, &0, &1000, &expiry);\n    assert_eq!(result, Err(Ok(Error::InvalidAmount)));\n\n    // Test amount too large\n    let result = client.try_create_order(&user, &2_000_000_000, &1000, &expiry);\n    assert_eq!(result, Err(Ok(Error::AmountTooLarge)));\n}\n\n#[test]\nfn test_validation_expiry() {\n    let env = Env::default();\n    let contract_id = env.register_contract(None, ValidatedContract);\n    let client = ValidatedContractClient::new(&env, &contract_id);\n\n    let user = Address::generate(&env);\n    let current_time = env.ledger().timestamp();\n\n    env.mock_all_auths();\n\n    // Test expiry in past\n    let result = client.try_create_order(&user, &100, &1000, &(current_time - 1));\n    assert_eq!(result, Err(Ok(Error::ExpiryInPast)));\n\n    // Test expiry too far\n    let far_future = current_time + (60 * 24 * 60 * 60); // 60 days\n    let result = client.try_create_order(&user, &100, &1000, &far_future);\n    assert_eq!(result, Err(Ok(Error::ExpiryTooFar)));\n}\n"})})})]}),"\n",(0,a.jsx)(o.P,{variant:"tip",title:"Validation Best Practices",children:(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Validate all inputs at function entry - Provide specific error types for different validation\nfailures - Check business logic constraints (ranges, relationships) - Validate time-based\nparameters against ledger time"}),"\n"]})}),"\n",(0,a.jsx)(n.h2,{id:"security-considerations",children:"Security Considerations"}),"\n",(0,a.jsx)(o.P,{variant:"error",title:"Critical Security Practices",children:(0,a.jsxs)(n.ol,{children:["\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Never ignore errors"}),": Always handle ",(0,a.jsx)(n.code,{children:"Result"})," types explicitly"]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Validate before state changes"}),": Check all conditions before modifying storage"]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Use specific error types"}),": Avoid gen